import Foundation

/// A recorded coach voice from `Stimmen/stimmen.json` in the app bundle (generated by a build script).
public struct CoachVoice: Codable, Sendable, Hashable, Identifiable {
    public let id: String
    public let name: String
    /// The language the voice counts in (`de`, `tr`, `en`); `nil` for voices from before 22.11.2026.
    public let language: String?
    /// Short description per language (`de`, `tr`, `en`).
    public let description: [String: String]

    private enum CodingKeys: String, CodingKey {
        case id, name
        case language = "sprache"
        case description = "beschreibung"
    }

    public init(id: String, name: String, language: String?, description: [String: String]) {
        self.id = id
        self.name = name
        self.language = language
        self.description = description
    }

    /// "Deutsch · männlich, jung und locker": the counting language in the reader's language, then the description.
    public var localizedSubtitle: String {
        let reader = Locale(identifier: Self.readerLanguage)
        guard let language, let name = reader.localizedString(forLanguageCode: language) else {
            return localizedDescription
        }
        return "\(name.prefix(1).uppercased() + name.dropFirst()) · \(localizedDescription)"
    }

    /// The voices with those in `language` first, the rest in their bundle order.
    ///
    /// A trainer in Turkey should find a Turkish voice at the top without scrolling; nothing is hidden,
    /// because a German group can just as well want the English voice.
    public static func ordered(_ voices: [CoachVoice], for language: String) -> [CoachVoice] {
        voices.filter { $0.language == language } + voices.filter { $0.language != language }
    }

    static var readerLanguage: String { String(Locale.preferredLanguages.first?.prefix(2) ?? "en") }

    public var localizedDescription: String {
        description[Self.readerLanguage] ?? description["en"] ?? ""
    }

    /// All voices in the bundle; empty if none were generated.
    public static let all: [CoachVoice] = {
        guard
            let url = Bundle.main.url(forResource: "stimmen", withExtension: "json", subdirectory: "Stimmen"),
            let data = try? Data(contentsOf: url)
        else { return [] }
        return (try? JSONDecoder().decode([CoachVoice].self, from: data)) ?? []
    }()
}
